import { z } from 'zod';
import { convertImageSchema, analyzeSpatialLayoutSchema } from '../../src/mcp/tools';
import { EvalResult } from '../eval-runner';

export async function runToolCallingEval(): Promise<EvalResult> {
  const convertValidator = z.object(convertImageSchema);
  const layoutValidator = z.object(analyzeSpatialLayoutSchema);

  // Simulated payloads generated by LLMs
  const validAgentPayloads = [
    {
      source: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
      width: 40,
      dithering: 'atkinson',
      charset: 'normal'
    },
    {
      source: './images/logo.png',
      width: 100,
      colorMode: 'color',
      useEdgeDetection: true,
      edgeIntensity: 1.5
    },
    {
      source: 'https://example.com/photo.jpg',
      contrast: 120,
      brightness: 110,
      useSharpen: true
    }
  ];

  let passedCases = 0;

  for (const payload of validAgentPayloads) {
    const parseResult = convertValidator.safeParse(payload);
    if (parseResult.success) {
      passedCases++;
    }
  }

  // Layout payload
  const layoutPayload = {
    source: './diagram.png',
    width: 60,
    edgeIntensity: 1.2
  };
  if (layoutValidator.safeParse(layoutPayload).success) {
    passedCases++;
  }

  const total = validAgentPayloads.length + 1;
  const score = passedCases / total;

  return {
    name: 'Tool-Calling Schema Adherence',
    passed: score === 1.0,
    score,
    details: `Successfully validated ${passedCases}/${total} synthetic agent tool-calling payloads against Zod schemas without type violations.`,
    metrics: { validPayloads: passedCases, totalCases: total }
  };
}
